/**
 * Test support for wide models: the backend's OpenAPI document of its
 * 120-field test product (generated by the Python suite as
 * packages/karni/tests/api/fixtures/schema.wideapp.json, copied to
 * tests/fixtures/), rows as its API returns them, and msw handlers that
 * serve both.
 *
 * The product has twelve markdown sections, five field groups (Overview,
 * Specifications, Financials, Content, Measurements; the rest go into Other)
 * and three column sets (default, financial, logistics).
 *
 * Test support only. Never imported by shipped component code.
 */
import { http, HttpResponse, type RequestHandler } from "msw";
import snapshot from "../../../tests/fixtures/schema.wideapp.json";

/** The OpenAPI document `/api/schema/` serves for the wide-model test app. */
export const wideOpenApi = snapshot as unknown as Record<string, unknown>;

/** The markdown sections, in declaration order. */
export const SECTIONS = [
  "overview",
  "features",
  "specifications",
  "materials",
  "assembly",
  "care",
  "safety",
  "warranty",
  "shipping",
  "returns",
  "sustainability",
  "faq",
] as const;

/** `["price_01", "price_02", ...]`. */
export function numbered(prefix: string, count: number): string[] {
  return Array.from(
    { length: count },
    (_, index) => `${prefix}_${String(index + 1).padStart(2, "0")}`,
  );
}

const BRAND = { id: "6a1f0c52-8d4e-4c3b-9f2a-1b2c3d4e5f60", name: "House brand" };

/** A markdown section of about 400 characters, as the backend's sample rows have. */
export function section(name: string, index: number): string {
  return [
    `## ${name.charAt(0).toUpperCase()}${name.slice(1)} of product ${index}`,
    "",
    "This section describes the product in the words a catalog uses: what it is made of, how " +
      "it is used and what it needs. It is long enough to wrap over several lines in a form and " +
      "on a detail page.",
    "",
    "- The first point, with **bold** text",
    "- The second point, with a [link](https://example.com/catalog)",
    "- The third point, with `code`",
    "",
  ].join("\n");
}

/** Product `index` as `GET /api/products/<id>/` returns it (125 keys). */
export function wideProduct(index: number): Record<string, unknown> {
  const id = `00000000-0000-4000-8000-${String(index).padStart(12, "0")}`;
  const row: Record<string, unknown> = {
    id,
    created_at: "2026-10-01T09:00:00Z",
    updated_at: "2026-10-02T09:00:00Z",
    created_by: null,
    updated_by: null,
    name: `Product ${String(index).padStart(3, "0")}`,
    sku: `SKU-${String(index).padStart(5, "0")}`,
    brand: BRAND.id,
    status: "active",
    grade: "b",
  };
  for (const name of SECTIONS) row[name] = section(name, index);
  for (const name of numbered("dimension", 20)) row[name] = `${12.5 + index}`;
  for (const name of numbered("metric", 20)) row[name] = 1000 + index;
  for (const name of numbered("flag", 15)) row[name] = index % 2 === 0;
  for (const name of numbered("label", 28)) row[name] = `Label ${name} of ${index}`;
  for (const name of numbered("date", 10)) row[name] = "2026-01-01";
  for (const name of numbered("price", 6)) row[name] = "199.9900";
  for (const name of numbered("rate", 4)) row[name] = "12.50";
  return row;
}

/** msw handlers: the wide schema, the products list and detail, and the brands list. */
export function wideHandlers(rows: ReadonlyArray<Record<string, unknown>>): RequestHandler[] {
  return [
    http.get("*/api/schema/", () => HttpResponse.json(wideOpenApi)),
    http.get("*/api/products/", ({ request }) => {
      const url = new URL(request.url);
      const size = Number(url.searchParams.get("page_size") ?? "25");
      return HttpResponse.json({
        count: rows.length,
        next: null,
        previous: null,
        results: rows.slice(0, size),
      });
    }),
    http.get("*/api/products/:id/", ({ params }) => {
      const found = rows.find((row) => row["id"] === params["id"]);
      return found !== undefined
        ? HttpResponse.json(found)
        : HttpResponse.json({ detail: "Not found." }, { status: 404 });
    }),
    http.get("*/api/brands/", () =>
      HttpResponse.json({ count: 1, next: null, previous: null, results: [BRAND] }),
    ),
  ];
}
